SELECT ?film ?filmLabel ?director ?directorLabel WHERE {
  VALUES ?film { dbr:Rhythm_in_the_Clouds dbr:September_Affair }
  ?film dbo:director ?director .
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel), "EN")) }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN")) }
}

SELECT ?director ?directorLabel WHERE {
  dbr:Rhythm_in_the_Clouds dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN")) }
}

SELECT ?film ?filmLabel ?director ?directorLabel ?deathDateLit ?deathYear WHERE {
  VALUES ?film { dbr:Rhythm_in_the_Clouds dbr:September_Affair }
  ?film dbo:director ?director .
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel),"EN")) }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel),"EN")) }
  OPTIONAL { ?director dbo:deathDate ?deathDate . }
  OPTIONAL { ?director dbp:deathDate ?deathDateDBP . }
  OPTIONAL { ?director dbo:abstract ?abstract . FILTER(langMatches(lang(?abstract),"EN")) }
  BIND( COALESCE(?deathDate, ?deathDateDBP) AS ?deathDateLit )
  BIND( IF(datatype(?deathDateLit)=xsd:date, YEAR(?deathDateLit), xsd:integer(REPLACE(str(COALESCE(?deathDateLit, ?abstract)), '^.*([0-9]{4})[^0-9]*$', '$1'))) AS ?deathYear )
} ORDER BY ?film

SELECT ?director ?abstract ( xsd:integer(REPLACE(str(?abstract), '^.*([0-9]{4})[^0-9]*$', '$1')) AS ?deathYear ) WHERE { 
  BIND(dbr:John_H._Auer AS ?director) .
  ?director dbo:abstract ?abstract . FILTER(langMatches(lang(?abstract),'EN'))
}

SELECT ?director ?abstract ( xsd:integer(REPLACE(str(?abstract), '^.*–[^0-9]*([0-9]{4}).*$', '$1')) AS ?deathYear ) WHERE { 
  BIND(dbr:John_H._Auer AS ?director) .
