PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT ?film ?filmLabel ?director ?directorLabel ?deathYear WHERE {
  VALUES ?film {
    dbr:Rhythm_in_the_Clouds dbr:September_Affair
  }
  ?film dbo:director ?director .
  OPTIONAL {
    ?film rdfs:label ?filmLabel
    FILTER(langMatches(lang(?filmLabel) , "EN"))
  }
  OPTIONAL {
    ?director rdfs:label ?directorLabel
    FILTER(langMatches(lang(?directorLabel) , "EN"))
  }
  OPTIONAL {
    ?director dbo:deathDate ?dbodeath .
  }
  OPTIONAL {
    ?director dbp:deathDate ?dbpdeath .
  }
  OPTIONAL {
    ?director dbo:abstract ?abstractFR
    FILTER(langMatches(lang(?abstractFR) , "FR"))
  }
  BIND(COALESCE(?dbodeath , ?dbpdeath) AS ?deathLit)
  BIND(IF(datatype(?deathLit) = xsd:date , YEAR(?deathLit) , xsd:integer(REPLACE(str(COALESCE(?deathLit , ?abstractFR)) , '^.*([0-9]{4})[^0-9]*$' , '$1'))) AS ?deathYear)
}

